--
-- Name: v_ips_chunks; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_ips_chunks AS
 SELECT x.id,
    x.client_id,
    COALESCE(NULLIF(btrim(c.name), ''::text), x.client_id) AS client_name,
    x.version,
    x.part_n,
    x.chunk_idx,
    x.text
   FROM (public.cp_ips_chunks x
     LEFT JOIN public.cp_clients c ON ((c.id = x.client_id)));


--
-- Name: v_ips_versions; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_ips_versions AS
 SELECT x.client_id,
    COALESCE(NULLIF(btrim(c.name), ''::text), x.client_id) AS client_name,
    x.version,
    x.status,
    x.issued_on,
    x.author,
    x.summary,
    x.parts
   FROM (public.cp_ips_versions x
     LEFT JOIN public.cp_clients c ON ((c.id = x.client_id)));


